/*
 * Audio stream reducer: mono mixdown, mono-to-stereo duplication and
 * low-pass decimation by 1, 2 or 4, applied to decoded S16 PCM before it
 * enters the stream's PCM ring (AUDIO_STREAM_BEGIN / BEGIN_EX output_hz and
 * output_channels, ZZ9K_SERVICE_FLAG_AUDIO_STREAM_REDUCE).
 *
 * Pure C with no firmware dependencies so the host tests drive the exact
 * production code. A zero-filled struct is a passthrough reducer.
 *
 * Decimation runs through a 59-tap linear-phase half-band FIR
 * (audio_reduce_table.h, generated by util/gen_audio_reduce_table.py) and
 * keeps every second output; a divisor of 4 cascades two stages. The FIR
 * history and the decimation phase persist across audio_reduce_run() calls,
 * so any split of the input into calls yields the same output. Stereo
 * sources mixed down to mono are averaged at the input rate before the
 * filter; a mono source duplicated to stereo is filtered once and copied.
 *
 * SPDX-License-Identifier: GPL-3.0-or-later
 */

#ifndef AUDIO_REDUCE_H
#define AUDIO_REDUCE_H

#include <stdint.h>

#include "audio_reduce_table.h"

#define AUDIO_REDUCE_MAX_CHANNELS 2U

/* One decimate-by-2 stage. Both channels advance in lockstep, so the
 * write slot and the output phase are shared. Each delay line holds the
 * history twice (slot and slot + TAPS) so the newest TAPS samples stay
 * contiguous without index wrapping in the multiply loop. */
struct audio_reduce_stage {
	int16_t line[AUDIO_REDUCE_MAX_CHANNELS][2U * AUDIO_REDUCE_TAPS];
	uint8_t pos;
	uint8_t phase;
};

struct audio_reduce {
	/* BEGIN request: 0 = the stream's own rate / channel count. */
	uint32_t req_hz;
	uint32_t req_channels;
	/* Decoder format; 0 until audio_reduce_set_input(). */
	uint32_t in_hz;
	uint32_t in_channels;
	/* Format written to the PCM ring. */
	uint32_t out_hz;
	uint32_t out_channels;
	/* 1, 2 or 4 once configured; 0 = not configured (passthrough). */
	uint32_t divisor;
	struct audio_reduce_stage stage[2];
};

/* Smallest divisor d in {1, 2, 4} with stream_hz / d <= output_hz, or 4
 * when none fits. output_hz 0 means no limit (1). */
uint32_t audio_reduce_divisor(uint32_t stream_hz, uint32_t output_hz);

/* Record the BEGIN request and clear all state. Returns 0, or -1 when
 * output_channels is not 0, 1 or 2. */
int audio_reduce_request(struct audio_reduce *r, uint32_t output_hz,
                         uint32_t output_channels);

/* Announce the decoder format. Selects the divisor and output format and
 * clears the filter state when hz or channels differ from the current
 * input; returns 1 in that case, 0 when nothing changed (or hz/channels
 * is 0). Only 1 and 2 channels are reduced; other counts pass through. */
int audio_reduce_set_input(struct audio_reduce *r, uint32_t hz,
                           uint32_t channels);

/* True when audio_reduce_run() changes the data. */
int audio_reduce_active(const struct audio_reduce *r);

/* Decoder bytes that stay within `ring_free` ring bytes once reduced. Only
 * mono to stereo grows the data: twice at divisor 1, and at divisor 2 or 4
 * the room depends on the decimation phase each stage carries, so an empty
 * ring takes a raw block as large as itself. */
uint32_t audio_reduce_raw_room(const struct audio_reduce *r,
                               uint32_t ring_free);

/* Decoder bytes that correspond to `ring_bytes` of reduced output. */
uint32_t audio_reduce_raw_bytes(const struct audio_reduce *r,
                                uint32_t ring_bytes);

/* Reduce `frames` input frames (in_channels interleaved S16 samples each)
 * into `out` (out_channels per frame) and return the output frame count,
 * at most frames / divisor + 1. `in` and `out` must not overlap. */
uint32_t audio_reduce_run(struct audio_reduce *r, const int16_t *in,
                          uint32_t frames, int16_t *out);

#endif /* AUDIO_REDUCE_H */
